CREATE TRIGGER IF NOT EXISTS v274_provider_active_successor_receipt_projection
BEFORE INSERT ON compute_external_pool_adapter_provider_active_successor_receipts
WHEN NEW.active_successor_receipt_schema IS NOT json_extract(NEW.receipt_json,'$.schema')
 OR NEW.active_successor_receipt_id IS NOT json_extract(NEW.receipt_json,'$.active_successor_receipt_id')
