 OR NEW.canonicalization IS NOT json_extract(NEW.receipt_json,'$.canonicalization')
 OR NEW.digest_algorithm IS NOT json_extract(NEW.receipt_json,'$.digest_algorithm')
 OR NEW.provider_binding_id IS NOT json_extract(NEW.receipt_json,'$.successor.activation.activation_root.provider_binding_id')
