 OR NEW.registry_release_material_digest IS NOT json_extract(NEW.receipt_json,'$.successor.activation.activation_root.registry_release_material_digest')
 OR NEW.installation_receipt_id IS NOT json_extract(NEW.receipt_json,'$.successor.activation.activation_root.installation_receipt_id')
 OR NEW.installation_receipt_digest IS NOT json_extract(NEW.receipt_json,'$.successor.activation.activation_root.installation_receipt_digest')
 OR NEW.installation_content_digest IS NOT json_extract(NEW.receipt_json,'$.successor.activation.activation_root.installation_content_digest')
