 OR NEW.evidence_provider_policy_revision IS NOT json_extract(NEW.receipt_json,'$.successor.evidence_provider.provider_policy_revision')
 OR NEW.evidence_provider_json IS NOT json_extract(NEW.receipt_json,'$.successor.evidence_provider.provider_json')
 OR NEW.evidence_provider_digest IS NOT json_extract(NEW.receipt_json,'$.successor.evidence_provider.provider_digest')
 OR NEW.reattestation_receipt_id IS NOT json_extract(NEW.receipt_json,'$.successor.credential_evidence.reattestation_receipt_id')
