 OR NEW.runtime_observation_digest IS NOT json_extract(NEW.receipt_json,'$.successor.runtime_observation.runtime_observation_digest')
 OR NEW.runtime_observed_provider_id IS NOT json_extract(NEW.receipt_json,'$.successor.runtime_observation.observed_provider.provider_id')
 OR NEW.runtime_observed_provider_policy_revision IS NOT json_extract(NEW.receipt_json,'$.successor.runtime_observation.observed_provider.provider_policy_revision')
 OR NEW.runtime_observed_provider_json IS NOT json_extract(NEW.receipt_json,'$.successor.runtime_observation.observed_provider.provider_json')
 OR NEW.runtime_observed_provider_digest IS NOT json_extract(NEW.receipt_json,'$.successor.runtime_observation.observed_provider.provider_digest')
 OR NEW.observation_started_at IS NOT json_extract(NEW.receipt_json,'$.successor.runtime_observation.observation_started_at')
 OR NEW.observation_completed_at IS NOT json_extract(NEW.receipt_json,'$.successor.runtime_observation.observation_completed_at')
 OR NEW.observation_expires_at IS NOT json_extract(NEW.receipt_json,'$.successor.runtime_observation.observation_expires_at')
 OR NEW.task_protocol_conformance_run_receipt_id IS NOT json_extract(NEW.receipt_json,'$.successor.task_protocol_evidence.task_protocol_conformance_run_receipt_id')
 OR NEW.task_protocol_conformance_run_receipt_digest IS NOT json_extract(NEW.receipt_json,'$.successor.task_protocol_evidence.task_protocol_conformance_run_receipt_digest')
 OR NEW.task_protocol_conformance_expires_at IS NOT json_extract(NEW.receipt_json,'$.successor.task_protocol_evidence.task_protocol_conformance_expires_at')
 OR NEW.activation_witness_id IS NOT json_extract(NEW.receipt_json,'$.successor.activation_witness.activation_witness_id')
 OR NEW.activation_witness_digest IS NOT json_extract(NEW.receipt_json,'$.successor.activation_witness.activation_witness_digest')
 OR NEW.checked_at IS NOT json_extract(NEW.receipt_json,'$.successor.checked_at')
 OR NEW.created_at IS NOT json_extract(NEW.receipt_json,'$.successor.created_at')
 OR NEW.effects_json IS NOT json_extract(NEW.receipt_json,'$.successor.effects')
 OR NEW.readiness_json IS NOT json_extract(NEW.receipt_json,'$.successor.readiness')
BEGIN SELECT RAISE(ABORT,'V274 active successor scalar/canonical projection mismatch'); END;

CREATE TRIGGER IF NOT EXISTS v274_provider_active_successor_revocation_projection
BEFORE INSERT ON compute_external_pool_adapter_provider_active_successor_revocations
WHEN NEW.active_successor_revocation_schema IS NOT json_extract(NEW.revocation_json,'$.schema')
 OR NEW.active_successor_revocation_id IS NOT json_extract(NEW.revocation_json,'$.active_successor_revocation_id')
 OR NEW.revocation_digest IS NOT json_extract(NEW.revocation_json,'$.revocation_digest')
 OR NEW.canonicalization IS NOT json_extract(NEW.revocation_json,'$.canonicalization')
 OR NEW.digest_algorithm IS NOT json_extract(NEW.revocation_json,'$.digest_algorithm')
 OR NEW.target_active_successor_receipt_id IS NOT json_extract(NEW.revocation_json,'$.revocation.target_active_successor_receipt_id')
 OR NEW.target_active_successor_receipt_digest IS NOT json_extract(NEW.revocation_json,'$.revocation.target_active_successor_receipt_digest')
 OR NEW.provider_binding_id IS NOT json_extract(NEW.revocation_json,'$.revocation.provider_binding_id')
 OR NEW.activation_root_digest IS NOT json_extract(NEW.revocation_json,'$.revocation.activation_root_digest')
 OR NEW.revoked_by_actor_kind IS NOT json_extract(NEW.revocation_json,'$.revocation.revoked_by_actor_kind')
 OR NEW.revoked_by_actor_user_id IS NOT json_extract(NEW.revocation_json,'$.revocation.revoked_by_actor_user_id')
 OR NEW.reason_code IS NOT json_extract(NEW.revocation_json,'$.revocation.reason_code')
 OR NEW.idempotency_scope IS NOT json_extract(NEW.revocation_json,'$.revocation.idempotency_scope')
 OR NEW.idempotency_key IS NOT json_extract(NEW.revocation_json,'$.revocation.idempotency_key')
 OR NEW.idempotency_digest IS NOT json_extract(NEW.revocation_json,'$.revocation.idempotency_digest')
 OR NEW.confirmation IS NOT json_extract(NEW.revocation_json,'$.revocation.confirmation')
 OR NEW.confirmation_digest IS NOT json_extract(NEW.revocation_json,'$.revocation.confirmation_digest')
 OR NEW.revoked_at IS NOT json_extract(NEW.revocation_json,'$.revocation.revoked_at')
 OR NEW.effects_json IS NOT json_extract(NEW.revocation_json,'$.revocation.effects')
 OR NEW.readiness_json IS NOT json_extract(NEW.revocation_json,'$.revocation.readiness')
BEGIN SELECT RAISE(ABORT,'V274 active successor revocation projection mismatch'); END;
